You could use the suggested `taskResultDefault` here as well, combined with an helper to convert that result to a matrixed default, e.g.

```golang
func matrixedDefaultValue(def *v1.ResultValue) (v1.ParamValue, error) {
	switch def.Type {
	case v1.ParamTypeArray:
		return *def, nil
	case v1.ParamTypeString:
		return v1.ParamValue{Type: v1.ParamTypeArray, ArrayVal: []string{def.StringVal}}, nil
	default:
		return v1.ParamValue{}, fmt.Errorf("object defaults are not supported for matrixed tasks")
	}
}
```

